import { MongoClient, Db, Collection, Filter } from 'mongodb';
import { createHash } from 'crypto';
import * as argon2 from 'argon2';

// Feature flag configuration
interface FeatureFlags {
  enableQueryCache: boolean;
  enableFieldProjection: boolean;
  enableAggregationPipeline: boolean;
  queryOptimizationLevel: number;
}

interface UserQuery {
  collection: string;
  filters: Record<string, unknown>;
  projection?: Record<string, number>;
  limit?: number;
}

class QuerySanitizer {
  private static readonly DANGEROUS_OPERATORS = ['$where', '$accumulator', '$function'];
  private static readonly ALLOWED_OPERATORS = ['$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin', '$regex', '$exists'];

  static sanitizeValue(value: unknown, depth: number = 0): unknown {
    if (depth > 10) throw new Error('Query too deeply nested');
    if (value === null || value === undefined) return value;
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      return value;
    }
    if (Array.isArray(value)) {
      return value.map(item => QuerySanitizer.sanitizeValue(item, depth + 1));
    }
    if (typeof value === 'object') {
      return QuerySanitizer.sanitizeObject(value as Record<string, unknown>, depth + 1);
    }
    throw new Error(`Unsupported value type: ${typeof value}`);
  }

  static sanitizeObject(obj: Record<string, unknown>, depth: number = 0): Record<string, unknown> {
    if (depth > 10) throw new Error('Query too deeply nested');
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(obj)) {
      if (key.startsWith('$')) {
        if (QuerySanitizer.DANGEROUS_OPERATORS.includes(key)) {
          throw new Error(`Operator ${key} is not allowed`);
        }
        if (!QuerySanitizer.ALLOWED_OPERATORS.includes(key)) {
          throw new Error(`Unknown operator: ${key}`);
        }
      }
      sanitized[key] = QuerySanitizer.sanitizeValue(value, depth + 1);
    }
    return sanitized;
  }
}

class QueryOptimizer {
  private flags: FeatureFlags;

  constructor(flags: FeatureFlags) {
    this.flags = flags;
  }

  optimizeFilter(filter: Record<string, unknown>): Record<string, unknown> {
    if (this.flags.queryOptimizationLevel === 0) {
      return filter;
    }
    // Level 1: Flatten single-element $and/$or
    if (this.flags.queryOptimizationLevel >= 1) {
      filter = this.flattenSingleElementLogical(filter);
    }
    // Level 2: Merge equality conditions
    if (this.flags.queryOptimizationLevel >= 2) {
      filter = this.mergeEqualityConditions(filter);
    }
    return filter;
  }

  private flattenSingleElementLogical(filter: Record<string, unknown>): Record<string, unknown> {
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(filter)) {
      if ((key === '$and' || key === '$or') && Array.isArray(value) && value.length === 1) {
        Object.assign(result, value[0]);
      } else {
        result[key] = value;
      }
    }
    return result;
  }

  private mergeEqualityConditions(filter: Record<string, unknown>): Record<string, unknown> {
    // Optimization: convert {field: {$eq: val}} to {field: val}
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(filter)) {
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        const obj = value as Record<string, unknown>;
        const keys = Object.keys(obj);
        if (keys.length === 1 && keys[0] === '$eq') {
          result[key] = obj['$eq'];
        } else {
          result[key] = value;
        }
      } else {
        result[key] = value;
      }
    }
    return result;
  }
}

class SecureQueryService {
  private db: Db;
  private flags: FeatureFlags;
  private optimizer: QueryOptimizer;
  private queryCache: Map<string, unknown[]>;
  private static readonly ALLOWED_COLLECTIONS = ['users', 'products', 'orders', 'reviews'];

  constructor(db: Db, flags: FeatureFlags) {
    this.db = db;
    this.flags = flags;
    this.optimizer = new QueryOptimizer(flags);
    this.queryCache = new Map();
  }

  private validateCollection(name: string): void {
    if (!SecureQueryService.ALLOWED_COLLECTIONS.includes(name)) {
      throw new Error(`Collection '${name}' is not accessible`);
    }
  }

  private getCacheKey(query: UserQuery): string {
    return createHash('sha256').update(JSON.stringify(query)).digest('hex');
  }

  async executeQuery(query: UserQuery): Promise<unknown[]> {
    this.validateCollection(query.collection);

    // Phase 1: Sanitize the raw input
    const sanitizedFilters = QuerySanitizer.sanitizeObject(query.filters);

    // Phase 2: Apply query optimization based on feature flags
    const optimizedFilters = this.optimizer.optimizeFilter(sanitizedFilters);

    // Phase 3: Build the final query with feature-flag-dependent behavior
    const finalQuery = this.buildFinalQuery(optimizedFilters, query);

    // Phase 4: Check cache
    if (this.flags.enableQueryCache) {
      const cacheKey = this.getCacheKey(query);
      const cached = this.queryCache.get(cacheKey);
      if (cached) return cached;
    }

    // Phase 5: Execute
    const collection = this.db.collection(query.collection);
    let cursor = collection.find(finalQuery.filter);

    if (finalQuery.projection) {
      cursor = cursor.project(finalQuery.projection);
    }

    cursor = cursor.limit(Math.min(query.limit || 50, 100));
    const results = await cursor.toArray();

    if (this.flags.enableQueryCache) {
      const cacheKey = this.getCacheKey(query);
      this.queryCache.set(cacheKey, results);
    }

    return results;
  }

  private buildFinalQuery(filters: Record<string, unknown>, query: UserQuery): {
    filter: Filter<any>;
    projection?: Record<string, number>;
  } {
    let finalFilter: Record<string, unknown> = { ...filters };

    // Feature flag: when aggregation pipeline is enabled, support $expr-like syntax
    // by re-parsing the original query filters for advanced operators
    if (this.flags.enableAggregationPipeline) {
      finalFilter = this.enhanceWithAggregationSupport(query.filters, finalFilter);
    }

    let projection: Record<string, number> | undefined;
    if (this.flags.enableFieldProjection && query.projection) {
      projection = this.sanitizeProjection(query.projection);
    }

    return { filter: finalFilter as Filter<any>, projection };
  }

  private enhanceWithAggregationSupport(
    originalFilters: Record<string, unknown>,
    sanitizedFilters: Record<string, unknown>
  ): Record<string, unknown> {
    // When aggregation is enabled, we allow $expr for computed field comparisons
    // We merge the sanitized base with any $expr from the original input
    const enhanced = { ...sanitizedFilters };
    if ('$expr' in originalFilters && typeof originalFilters['$expr'] === 'object') {
      // $expr allows comparison operators on fields - considered safe as it
      // doesn't execute arbitrary code like $where
      enhanced['$expr'] = originalFilters['$expr'];
    }
    return enhanced;
  }

  private sanitizeProjection(projection: Record<string, number>): Record<string, number> {
    const sanitized: Record<string, number> = {};
    for (const [key, value] of Object.entries(projection)) {
      if (typeof value === 'number' && (value === 0 || value === 1)) {
        if (!key.startsWith('$') && /^[a-zA-Z_][a-zA-Z0-9_.]*$/.test(key)) {
          sanitized[key] = value;
        }
      }
    }
    return sanitized;
  }
}

export { SecureQueryService, FeatureFlags, UserQuery, QuerySanitizer, QueryOptimizer };
